import React, { useState } from "react";
import { Dashboard } from "./components/Dashboard";
import { Sidebar } from "./components/Sidebar";
import { Header } from "./components/Header";
import { ClientsView } from "./components/ClientsView";
import { TasksView } from "./components/TasksView";
import { WorkerMetrics } from "./components/WorkerMetrics";
import { Settings } from "./components/Settings";
import { LanguageAnimationDemo } from "./components/LanguageAnimationDemo";
import { StatusProvider, useStatus } from "./contexts/StatusContext";
import { SettingsProvider } from "./contexts/SettingsContext";
import { I18nProvider } from "./contexts/I18nContext";
import { PageTransition } from "./components/PageTransition";

const AppContent: React.FC = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [currentView, setCurrentView] = useState("dashboard");
  const { state } = useStatus();

  // Функція для рендерингу поточної сторінки з анімацією
  const renderCurrentPage = () => {
    switch (currentView) {
      case "dashboard":
        return (
          <PageTransition pageKey="dashboard" animationType="dashboard">
            <Dashboard />
          </PageTransition>
        );
      case "clients":
        return (
          <PageTransition pageKey="clients" animationType="clients">
            <ClientsView />
          </PageTransition>
        );
      case "tasks":
        return (
          <PageTransition pageKey="tasks" animationType="tasks">
            <TasksView />
          </PageTransition>
        );
      case "metrics":
        return (
          <PageTransition pageKey="metrics" animationType="metrics">
            <WorkerMetrics clients={state.clients} />
          </PageTransition>
        );
      case "settings":
        return (
          <PageTransition pageKey="settings" animationType="settings">
            <Settings />
          </PageTransition>
        );
      case "animation-demo":
        return (
          <PageTransition pageKey="animation-demo" animationType="default">
            <LanguageAnimationDemo />
          </PageTransition>
        );
      default:
        return (
          <PageTransition pageKey="dashboard" animationType="dashboard">
            <Dashboard />
          </PageTransition>
        );
    }
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {/* Header */}
      <Header
        sidebarOpen={sidebarOpen}
        setSidebarOpen={setSidebarOpen}
        sidebarCollapsed={sidebarCollapsed}
        setSidebarCollapsed={setSidebarCollapsed}
      />

      {/* Sidebar */}
      <Sidebar
        isOpen={sidebarOpen}
        isCollapsed={sidebarCollapsed}
        onToggle={() => setSidebarOpen(!sidebarOpen)}
        onCollapse={() => setSidebarCollapsed(!sidebarCollapsed)}
        currentView={currentView}
        onViewChange={setCurrentView}
      />

      {/* Main Content */}
      <main
        className={`pt-16 transition-all duration-300 content-shift ${
          sidebarCollapsed ? "lg:ml-20" : "lg:ml-64"
        }`}
      >
        <div className="p-6">{renderCurrentPage()}</div>
      </main>

      {/* Demo Button - тимчасово для тестування */}
      <div className="fixed bottom-4 right-4 z-50">
        <button
          onClick={() => setCurrentView(currentView === "animation-demo" ? "dashboard" : "animation-demo")}
          className="bg-purple-500 hover:bg-purple-600 text-white px-4 py-2 rounded-lg shadow-lg transition-colors"
        >
          {currentView === "animation-demo" ? "🏠 Dashboard" : "🎨 Animation Demo"}
        </button>
      </div>
    </div>
  );
};

function App() {
  return (
    <SettingsProvider>
      <I18nProvider>
        <StatusProvider>
          <AppContent />
        </StatusProvider>
      </I18nProvider>
    </SettingsProvider>
  );
}

export default App;
